package com.fongmi.android.tv.server.cloud;
import com.github.catvod.net.OkHttp;
import org.json.JSONObject;
import okhttp3.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
/** Official Tianyi web QR flow; no credential is returned to LAN clients. */
public final class CloudTianyiQr {
 private static final String CLOUD="https://cloud.189.cn", AUTH="https://open.e.189.cn", RETURN=CLOUD+"/web/redirect.html";
 private static final Map<String,Session> sessions=new ConcurrentHashMap<>();
 private static final class Session implements CookieJar {
  final String browser=UUID.randomUUID().toString().replace("-", ""); final List<Cookie> cookies=new ArrayList<>();
  final Map<String,String> headers=new HashMap<>(); final long expires=System.currentTimeMillis()+240000;
  final OkHttpClient client=OkHttp.client(30000).newBuilder().cookieJar(this).followRedirects(false).followSslRedirects(false).build();
  String name,param,returnUrl,isOauth,state,authorized; JSONObject qr,result; boolean exchanged,cancelled;
  public synchronized void saveFromResponse(HttpUrl url,List<Cookie> incoming){for(Cookie c:incoming){if(!c.matches(url))continue;cookies.removeIf(x->x.name().equals(c.name())&&x.domain().equals(c.domain())&&x.path().equals(c.path()));cookies.add(c);}}
  public synchronized List<Cookie> loadForRequest(HttpUrl url){List<Cookie> out=new ArrayList<>();for(Cookie c:cookies)if(c.matches(url)&&c.expiresAt()>System.currentTimeMillis())out.add(c);return out;}
 }
 private static boolean official(HttpUrl u){return u!=null&&u.isHttps()&&u.port()==443&&u.username().isEmpty()&&u.password().isEmpty()&&Arrays.asList("cloud.189.cn","open.e.189.cn","m.cloud.189.cn","api.cloud.189.cn").contains(u.host());}
 private static Response request(Session s,String value,FormBody body)throws Exception{
  HttpUrl url=HttpUrl.parse(value);for(int i=0;i<12;i++){if(s.cancelled)throw new IllegalStateException("扫码已取消");if(!official(url))throw new IllegalStateException("非官方跳转已拒绝");Request.Builder b=new Request.Builder().url(url).header("User-Agent","Mozilla/5.0").header("Accept","application/json;charset=UTF-8").header("Browser-Id",s.browser);for(Map.Entry<String,String> e:s.headers.entrySet())b.header(e.getKey(),e.getValue());if(body!=null)b.post(body);Response r=s.client.newCall(b.build()).execute();if(Arrays.asList(301,302,303,307,308).contains(r.code())&&r.header("Location")!=null){HttpUrl next=url.resolve(r.header("Location"));r.close();url=next;body=null;continue;}if(!r.isSuccessful()){int code=r.code();r.close();throw new IllegalStateException("天翼官方接口HTTP "+code);}return r;}throw new IllegalStateException("天翼官方跳转过多");
 }
 private static FormBody form(String... values){FormBody.Builder b=new FormBody.Builder();for(int i=0;i<values.length;i+=2)b.add(values[i],values[i+1]);return b.build();}
 private static JSONObject post(Session s,String path,String... values)throws Exception{try(Response r=request(s,AUTH+path,form(values))){return parse(r.body().string());}}
 static JSONObject parse(String text)throws Exception{
  String raw=text.trim();if(raw.startsWith("{"))return new JSONObject(raw);
  if(raw.toUpperCase(Locale.ROOT).contains("<!DOCTYPE")||raw.toUpperCase(Locale.ROOT).contains("<!ENTITY"))throw new IllegalStateException("天翼官方XML格式无效");
  javax.xml.parsers.DocumentBuilderFactory f=javax.xml.parsers.DocumentBuilderFactory.newInstance();f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);f.setExpandEntityReferences(false);
  org.w3c.dom.Element root=f.newDocumentBuilder().parse(new java.io.ByteArrayInputStream(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8))).getDocumentElement();if("error".equals(root.getTagName()))throw new IllegalStateException("天翼官方返回错误");JSONObject out=element(root);return "fileListAO".equals(root.getTagName())?new JSONObject().put("fileListAO",out):out;
 }
 private static JSONObject element(org.w3c.dom.Element e)throws Exception{JSONObject out=new JSONObject();org.w3c.dom.NodeList nodes=e.getChildNodes();for(int i=0;i<nodes.getLength();i++){org.w3c.dom.Node n=nodes.item(i);if(!(n instanceof org.w3c.dom.Element))continue;org.w3c.dom.Element child=(org.w3c.dom.Element)n;boolean nested=false;for(int j=0;j<child.getChildNodes().getLength();j++)if(child.getChildNodes().item(j) instanceof org.w3c.dom.Element)nested=true;out.put(child.getTagName(),nested?element(child):child.getTextContent().trim());}return out;}
 static void directory(JSONObject value)throws Exception{String code=value.has("res_code")?value.optString("res_code"):value.has("errorCode")?value.optString("errorCode"):value.optString("code");JSONObject list=value.optJSONObject("fileListAO");if(!Arrays.asList("","0","SUCCESS").contains(code)||list==null||!(list.has("count")||list.has("fileList")||list.has("folderList")))throw new IllegalStateException("天翼未返回有效目录，请重新扫码登录");}
 private static String parameter(HttpUrl u,String text,String name){String v=u.queryParameter(name);if(v!=null)return v;java.util.regex.Matcher m=java.util.regex.Pattern.compile(name+"\\s*=\\s*\"([^\"]+)\"").matcher(text);return m.find()?m.group(1):"";}
 public static JSONObject start(String name)throws Exception{
  sessions.entrySet().removeIf(e->e.getValue().expires<System.currentTimeMillis());if(sessions.size()>=32)throw new IllegalStateException("扫码会话较多，请稍后再试");Session s=new Session();s.name=name;HttpUrl url=HttpUrl.parse(CLOUD+"/api/portal/loginUrl.action").newBuilder().addQueryParameter("redirectURL",RETURN).addQueryParameter("defaultSaveName","3").addQueryParameter("defaultSaveNameCheck","uncheck").addQueryParameter("browserId",s.browser).build();
  try(Response r=request(s,url.toString(),null)){String text=r.body().string(),lt=parameter(r.request().url(),text,"lt"),req=parameter(r.request().url(),text,"reqId");if(lt.isEmpty()||req.isEmpty())throw new IllegalStateException("天翼官方登录页缺少lt/reqId");s.headers.put("lt",lt);s.headers.put("REQID",req);s.headers.put("Referer",r.request().url().toString());s.headers.put("user-finger",UUID.randomUUID().toString().replace("-",""));}
  JSONObject conf=post(s,"/api/logbox/oauth2/appConf.do","version","2.0","appKey","cloud").getJSONObject("data");s.param=conf.getString("paramId");s.returnUrl=conf.optString("returnUrl",RETURN);s.isOauth=conf.optString("isOauth2","false");s.state=conf.optString("state");s.qr=post(s,"/api/logbox/oauth2/getUUID.do","appId","cloud");if(s.qr.optString("uuid").isEmpty()||s.qr.optString("encryuuid").isEmpty()||s.qr.optString("encodeuuid").isEmpty())throw new IllegalStateException("天翼二维码参数不完整");
  String image;try(Response r=request(s,HttpUrl.parse(AUTH+"/api/logbox/oauth2/image.do").newBuilder().addQueryParameter("uuid",s.qr.getString("encodeuuid")).addQueryParameter("REQID",s.headers.get("REQID")).build().toString(),null)){String mime=r.header("Content-Type","").split(";")[0];if(!mime.startsWith("image/"))throw new IllegalStateException("天翼未返回二维码图片");image="data:"+mime+";base64,"+android.util.Base64.encodeToString(r.body().bytes(),android.util.Base64.NO_WRAP);}
  String id="tianyi-web:"+UUID.randomUUID();sessions.put(id,s);return new JSONObject().put("sessionId",id).put("state","waiting").put("qrImage",image).put("expiresAt",s.expires).put("pollAfter",3000).put("message","请使用天翼云盘App扫码确认");
 }
 public static JSONObject cancel(String id)throws Exception{Session s=sessions.remove(id);if(s!=null)synchronized(s){s.cancelled=true;s.cookies.clear();}return new JSONObject().put("state","cancelled");}
 public static JSONObject poll(String id)throws Exception{Session s=sessions.get(id);if(s==null)throw new IllegalStateException("扫码会话不存在或已过期");synchronized(s){if(s.result!=null)return s.result;if(s.cancelled)return new JSONObject().put("state","cancelled");if(System.currentTimeMillis()>s.expires){sessions.remove(id);return new JSONObject().put("state","expired");}
  try{if(s.authorized==null){JSONObject status=post(s,"/api/logbox/oauth2/qrcodeLoginState.do","appId","cloud","clientType","1","returnUrl",java.net.URLEncoder.encode(s.returnUrl,"UTF-8"),"paramId",s.param,"uuid",s.qr.getString("uuid"),"encryuuid",s.qr.getString("encryuuid"),"cb_SaveName","3","isOauth2",s.isOauth,"state",s.state,"date",new java.text.SimpleDateFormat("yyyy-MM-ddHH:mm:ss",Locale.ROOT).format(new Date()),"timeStamp",String.valueOf(System.currentTimeMillis()));int code=status.optInt("status",-1);if(code==-106||code==-11002)return new JSONObject().put("state",code==-106?"waiting":"scanned").put("pollAfter",3000);if(code==-11001)return new JSONObject().put("state","expired");if(code!=0||status.optString("redirectUrl").isEmpty())throw new IllegalStateException("天翼扫码状态异常："+code);s.authorized=status.getString("redirectUrl");}
  if(!s.exchanged){try(Response r=request(s,s.authorized,null)){r.body().string();}s.exchanged=true;}check(s);StringJoiner cookie=new StringJoiner("; ");for(Cookie c:s.loadForRequest(HttpUrl.parse(CLOUD+"/")))cookie.add(c.name()+"="+c.value());if(cookie.length()==0)throw new IllegalStateException("天翼未返回登录Cookie");JSONObject saved=CloudAccountStore.save("","tianyi",s.name,new JSONObject().put("cookie",cookie.toString()).put("browser_id",s.browser));String account="";org.json.JSONArray accounts=saved.getJSONArray("accounts");for(int i=0;i<accounts.length();i++)if("tianyi".equals(accounts.getJSONObject(i).optString("provider")))account=accounts.getJSONObject(i).getString("id");s.result=CloudAccountStore.setValidation(account,"valid","天翼官方扫码及目录校验通过").put("state","complete").put("message","天翼登录有效");s.cookies.clear();return s.result;
  }catch(java.io.IOException e){return new JSONObject().put("state","waiting").put("pollAfter",5000).put("message","官方请求暂时超时，请稍候");}
 }}
 private static void check(Session s)throws Exception{try(Response r=request(s,CLOUD+"/api/open/file/listFiles.action?folderId=-11&pageNum=1&pageSize=1",null)){directory(parse(r.body().string()));}}
 public static JSONObject validate(String id)throws Exception{JSONObject account=CloudAccountStore.account(id),secret=account.getJSONObject("secret");if(account.optBoolean("disabled")||!"tianyi".equals(account.optString("provider")))throw new IllegalStateException("天翼账号不可用");String cookie=secret.optString("cookie");if(cookie.isBlank())throw new IllegalStateException("请先扫码登录天翼");Session s=new Session();s.headers.put("Browser-Id",secret.optString("browser_id",s.browser));s.headers.put("Referer",CLOUD+"/web/main/");for(String part:cookie.split(";")){Cookie c=Cookie.parse(HttpUrl.parse(CLOUD),part.trim()+"; Path=/; Secure");if(c!=null)s.cookies.add(c);}check(s);return CloudAccountStore.setValidation(id,"valid","天翼官方目录校验通过");}
}
